#!/usr/bin/env python3
"""数独求解器 - 使用回溯算法"""

def is_valid(board, row, col, num):
    """检查在 board[row][col] 位置放置数字 num 是否有效"""
    # 检查行
    for c in range(9):
        if board[row][c] == num:
            return False

    # 检查列
    for r in range(9):
        if board[r][col] == num:
            return False

    # 检查 3x3 宫格
    start_row = (row // 3) * 3
    start_col = (col // 3) * 3
    for r in range(start_row, start_row + 3):
        for c in range(start_col, start_col + 3):
            if board[r][c] == num:
                return False

    return True


def solve_sudoku(board):
    """使用递归回溯算法求解数独，返回 True/False"""
    # 查找下一个空白位置
    pos = find_empty(board)
    if not pos:
        # 没有空白位置，说明已填满，返回真
        return True

    row, col = pos

    # 尝试数字 1-9
    for num in range(1, 10):
        if is_valid(board, row, col, num):
            board[row][col] = num  # 放置数字

            # 递归求解
            if solve_sudoku(board):
                return True

            # 回溯
            board[row][col] = 0  # 撤销放置

    return False


def find_empty(board):
    """查找下一个空白位置"""
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return (r, c)
    return None


def main():
    # 读取谜题文件
    try:
        with open('puzzle.txt', 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("错误：无法找到 puzzle.txt 文件")
        exit(1)

    # 解析数独谜题
    board = []
    for line in lines:
        row = []
        for char in line.strip():
            row.append(int(char))
        board.append(row)

    # 求解数独
    print("开始求解数独...")
    if solve_sudoku(board):
        print("数独已求解完成！")
        # 写入解决方案
        with open('solution.txt', 'w', encoding='utf-8') as f:
            for row in board:
                f.write(''.join(str(d) for d in row) + '\n')
        print("解决方案已写入 solution.txt")
    else:
        print("错误：数独无解")
        exit(1)


if __name__ == '__main__':
    main()

