#!/usr/bin/env python3
"""Sudoku solver - using backtracking algorithm"""

import os
import sys

def is_valid(board, row, col, num):
    """Check if placing num at board[row][col] is valid"""
    # Check row
    for c in range(9):
        if board[row][c] == num:
            return False

    # Check column
    for r in range(9):
        if board[r][col] == num:
            return False

    # Check 3x3 box
    start_row = (row // 3) * 3
    start_col = (col // 3) * 3
    for r in range(start_row, start_row + 3):
        for c in range(start_col, start_col + 3):
            if board[r][c] == num:
                return False

    return True


def solve_sudoku(board):
    """Solve the sudoku using recursive backtracking, returns True/False"""
    # Find next empty position
    pos = find_empty(board)
    if not pos:
        # No empty positions, means completed, return True
        return True

    row, col = pos

    # Try numbers 1-9
    for num in range(1, 10):
        if is_valid(board, row, col, num):
            board[row][col] = num  # Place number

            # Recursively solve
            if solve_sudoku(board):
                return True

            # Backtrack
            board[row][col] = 0  # Undo placement

    return False


def find_empty(board):
    """Find next empty position"""
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return (r, c)
    return None


def main():
    # Get directory of the script as working directory
    script_dir = os.path.dirname(os.path.abspath(__file__))
    os.chdir(script_dir)

    # Read puzzle file
    try:
        with open('puzzle.txt', 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: Cannot find puzzle.txt file")
        exit(1)

    # Parse sudoku puzzle
    board = []
    for line in lines:
        row = []
        for char in line.strip():
            row.append(int(char))
        board.append(row)

    # Solve sudoku
    print("Start solving sudoku...")
    if solve_sudoku(board):
        print("Sudoku solved successfully!")
        # Write solution
        with open('solution.txt', 'w', encoding='utf-8') as f:
            for row in board:
                f.write(''.join(str(d) for d in row) + '\n')
        print("Solution written to solution.txt")
    else:
        print("Error: Sudoku has no solution")
        exit(1)


if __name__ == '__main__':
    main()
